using System.Diagnostics;
using SourceSharp.Host.Testing;

namespace SourceSharp.Host.Instances.Tests;

/// <summary>
/// deploy/game-entrypoint.sh as the pod runs it, under /bin/sh, with the launcher replaced by a
/// script that prints what it was given: the mod's resolved settings (mod.dedicated.yaml, the
/// sharp repo's `source# -resolve &lt;id&gt; -dedicated`) reach the launcher as args, env and fd limit.
/// </summary>
public sealed class EntrypointFacts : IDisposable
{
    // The sharp lane's sample, byte for byte.
    const string Sample =
        "# generated by source# -resolve; do not edit\n" +
        "fd_limit: 777\n" +
        "restart_exit_code: 42\n" +
        "args:\n" +
        "  - -console\n" +
        "  - -nohltv\n" +
        "  - +tv_enable\n" +
        "  - 0\n" +
        "env:\n" +
        "  SOURCESHARP_EXAMPLE: 1\n";

    readonly string _dir = Path.Combine(Path.GetTempPath(), "entrypoint-facts-" + Guid.NewGuid().ToString("N"));

    public EntrypointFacts()
    {
        Directory.CreateDirectory(Path.Combine(_dir, "game", "mods", "tf2_descent"));
        Directory.CreateDirectory(Path.Combine(_dir, "engine"));
        var launcher = Path.Combine(_dir, "launcher");
        File.WriteAllText(launcher,
            "#!/bin/sh\n" +
            "echo launched\n" +
            "for a in \"$@\"; do echo \"arg:$a\"; done\n" +
            "echo \"env:SOURCESHARP_EXAMPLE=${SOURCESHARP_EXAMPLE-unset}\"\n" +
            "echo \"env:SECOND=${SECOND-unset}\"\n" +
            "echo \"fd:$(ulimit -n)\"\n");
        // The facts run the entrypoint under /bin/sh; Windows has no unix file modes (CA1416).
        if (!OperatingSystem.IsWindows())
            File.SetUnixFileMode(launcher, UnixFileMode.UserRead | UnixFileMode.UserWrite | UnixFileMode.UserExecute);
    }

    public void Dispose() { try { Directory.Delete(_dir, recursive: true); } catch (IOException) { } }

    void Settings(string text) => File.WriteAllText(Path.Combine(_dir, "game", "mods", "tf2_descent", "mod.dedicated.yaml"), text);

    (int Exit, List<string> Out, string Err) Run(params string[] podArgs)
    {
        var psi = new ProcessStartInfo("/bin/sh") { RedirectStandardOutput = true, RedirectStandardError = true };
        psi.ArgumentList.Add(RepoFiles.Path_("deploy", "game-entrypoint.sh"));
        foreach (var a in podArgs) psi.ArgumentList.Add(a);
        psi.Environment["GAME_DIR"] = Path.Combine(_dir, "game");
        psi.Environment["ENGINE_DIR"] = Path.Combine(_dir, "engine");
        psi.Environment["TMPDIR"] = Path.Combine(_dir, "tmp");
        psi.Environment["SOURCESHARP_DEVAPI_DIR"] = Path.Combine(_dir, "devapi");
        psi.Environment["ENTRYPOINT_LAUNCHER"] = Path.Combine(_dir, "launcher");
        psi.Environment["SOURCESHARP_MOD"] = "tf2_descent";
        psi.Environment.Remove("SOURCESHARP_EXAMPLE");
        psi.Environment.Remove("SECOND");
        psi.Environment.Remove("REQUIRE_MOD");
        using var p = Process.Start(psi)!;
        var stdout = p.StandardOutput.ReadToEndAsync();
        var stderr = p.StandardError.ReadToEndAsync();
        p.WaitForExit();
        return (p.ExitCode, stdout.Result.Split('\n', StringSplitOptions.RemoveEmptyEntries).ToList(), stderr.Result);
    }

    static List<string> Args(List<string> output) => output.Where(l => l.StartsWith("arg:", StringComparison.Ordinal)).Select(l => l[4..]).ToList();

    [Fact]
    public void The_samples_args_come_before_the_pods()
    {
        Settings(Sample);
        var r = Run("-game", "/game/mods/tf2_descent", "+map", "tf2_descent-1-abc");
        Assert.True(r.Exit == 0, r.Err);
        Assert.Equal(["-console", "-nohltv", "+tv_enable", "0", "-game", "/game/mods/tf2_descent", "+map", "tf2_descent-1-abc"], Args(r.Out));
    }

    [Fact]
    public void The_samples_env_is_exported_to_the_launcher()
    {
        Settings(Sample);
        var r = Run();
        Assert.True(r.Exit == 0, r.Err);
        Assert.Contains("env:SOURCESHARP_EXAMPLE=1", r.Out);
    }

    [Fact]
    public void The_samples_fd_limit_is_applied()
    {
        Settings(Sample);
        var r = Run();
        Assert.True(r.Exit == 0, r.Err);
        Assert.Contains("fd:777", r.Out);
    }

    [Fact]
    public void Flow_empty_args_and_env_add_nothing()
    {
        Settings("# generated by source# -resolve; do not edit\nfd_limit: 777\nrestart_exit_code: 42\nargs: []\nenv: {}\n");
        var r = Run("+map", "tf2_descent-1-abc");
        Assert.True(r.Exit == 0, r.Err);
        Assert.Equal(["+map", "tf2_descent-1-abc"], Args(r.Out));
        Assert.Contains("env:SOURCESHARP_EXAMPLE=unset", r.Out);
    }

    [Fact]
    public void Block_empty_args_and_env_add_nothing()
    {
        Settings("# generated by source# -resolve; do not edit\nfd_limit: 777\nrestart_exit_code: 42\nargs:\nenv:\n");
        var r = Run("+map", "tf2_descent-1-abc");
        Assert.True(r.Exit == 0, r.Err);
        Assert.Equal(["+map", "tf2_descent-1-abc"], Args(r.Out));
    }

    [Fact]
    public void An_arg_or_value_with_spaces_stays_one_word()
    {
        Settings("fd_limit: 777\nrestart_exit_code: 42\nargs:\n  - +hostname\n  - Deep Mine\nenv:\n  SECOND: a b\n");
        var r = Run("+map", "two words");
        Assert.True(r.Exit == 0, r.Err);
        Assert.Equal(["+hostname", "Deep Mine", "+map", "two words"], Args(r.Out));
        Assert.Contains("env:SECOND=a b", r.Out);
    }

    [Fact]
    public void A_missing_settings_file_refuses_to_start()
    {
        var r = Run("+map", "tf2_descent-1-abc");
        Assert.Equal(64, r.Exit);
        Assert.DoesNotContain("launched", r.Out);
        Assert.Contains("mod.dedicated.yaml missing", r.Err);
    }

    [Fact]
    public void An_unknown_line_refuses_to_start()
    {
        Settings(Sample + "workers: 4\n");
        var r = Run();
        Assert.Equal(65, r.Exit);
        Assert.DoesNotContain("launched", r.Out);
    }

    /// <summary>plan_steam_auth S-18: the browser block as source# -resolve writes it (the game's byte-for-byte shape), last.</summary>
    const string Browser = """
        browser:
          name: "TF2 Descent ({levels_open} levels open)"
          description: "TF2 Descent"
          tags: "rpg,coop,descent,deepest{deepest}"
          region: ""
          max_players: 0
          map: "depth {deepest}"
          rules:
            players_by_level: "{players_by_level}"
            pool_ready: "{pool_ready}"

        """;

    [Fact]
    public void A_browser_block_is_skipped_and_changes_neither_args_nor_env()
    {
        Settings(Sample);
        var without = Run("+map", "m");
        Settings(Sample + Browser);
        var with = Run("+map", "m");
        Assert.True(without.Exit == 0, without.Err);
        Assert.True(with.Exit == 0, with.Err);
        Assert.Equal(Args(without.Out), Args(with.Out));
        Assert.Equal(without.Out.Where(l => l.StartsWith("env:", StringComparison.Ordinal)), with.Out.Where(l => l.StartsWith("env:", StringComparison.Ordinal)));
        Assert.Contains("launched", with.Out);
    }

    [Theory]
    [InlineData("browser: {}\n")]
    [InlineData("browser:\n  name: \"x\"\n  rules: {}\n")]
    public void An_empty_browser_block_or_empty_rules_start(string block)
    {
        Settings(Sample + block);
        var r = Run();
        Assert.True(r.Exit == 0, r.Err);
    }

    [Fact]
    public void An_unknown_key_after_a_browser_block_still_refuses_to_start()
    {
        Settings(Sample + Browser + "workers: 4\n");
        var r = Run();
        Assert.Equal(65, r.Exit);
        Assert.DoesNotContain("launched", r.Out);
    }

    [Fact]
    public void A_bad_environment_name_refuses_to_start()
    {
        Settings("fd_limit: 777\nrestart_exit_code: 42\nargs: []\nenv:\n  BAD-NAME: 1\n");
        var r = Run();
        Assert.Equal(65, r.Exit);
        Assert.DoesNotContain("launched", r.Out);
    }
}
